import type { SidebarsConfig } from "@docusaurus/plugin-content-docs";

// This runs in Node.js - Don't use client-side code here (browser APIs, JSX...)

/**
 * The sidebars of the current version, which `docusaurus docs:version` also
 * saves for every released version (see scripts/prepare.mts); the API docs
 * generated by typedoc are a category of the docs sidebar (see
 * `sidebarItemsGenerator` in tissuumaps-docs.ts; Docusaurus reads every
 * export of this file as a sidebar)
 */
const sidebars: SidebarsConfig = {
  // By default, Docusaurus generates a sidebar from the docs folder structure
  docsSidebar: [{ type: "autogenerated", dirName: "." }],
};

export default sidebars;
